// src/components/CartItem/CartItem.js
import React from 'react';
import { useDispatch } from 'react-redux';
import { addToCart } from '../../redyx/actions'; // правильний шлях до action creators
import './CartItem.css';

const CartItem = ({ item }) => {
  const dispatch = useDispatch();

  const handleAddToCart = () => {
    dispatch(addToCart(item)); // Додаємо товар в кошик
  };

  return (
    <div className="cart-item">
      <div className="item-details">
        <h3>{item.title}</h3>
        <p>Ціна: {item.price} грн</p>
        <button onClick={handleAddToCart}>Додати до кошика</button>
      </div>
    </div>
  );
};

export default CartItem;
